insert into public.insight_events (id, slug, title_he, title_en, description_he, description_en, resolution_criteria_he, resolution_criteria_en, horizon_hours, refresh_interval_hours, status, base_rate, keywords, min_tier, is_published, sort)
select id, slug, title_he, title_en, description_he, description_en, resolution_criteria_he, resolution_criteria_en, horizon_hours, refresh_interval_hours, status, base_rate, keywords, min_tier, is_published, sort from jsonb_populate_recordset(null::public.insight_events, E'[{"id": "f35078b8-900c-4595-b6db-38d6c51a3ff8", "slug": "iran-direct-confrontation", "sort": 0, "status": "active", "keywords": ["איראן", "איראני", "איראנית", "טהרן", "משמרות המהפכה", "חמינאי", "Iran", "Iranian", "Tehran", "IRGC", "Khamenei", "إيران", "الإيراني", "طهران", "الحرس الثوري", "خامنئي"], "min_tier": 1, "title_en": "Direct military confrontation between Israel/US and Iran within the next 24h", "title_he": "עימות צבאי ישיר בין ישראל/ארה\\"ב לאיראן ב-24 השעות הקרובות", "base_rate": 0.02, "is_published": true, "horizon_hours": 24, "description_en": "Estimated likelihood of a direct exchange of fire between Israel or the US and Iran.", "description_he": "הערכת הסבירות לחילופי אש ישירים בין ישראל או ארה\\"ב לבין איראן.", "refresh_interval_hours": 8, "resolution_criteria_en": "Resolves YES if, within the 24h window, the IDF or US forces strike a target on Iranian territory, or Iran launches missiles or drones directly from its territory at Israel or at a US target. Interceptions of Iranian projectiles en route and actions by proxies (Hezbollah, the Houthis and others) do not count as occurrence — they are signals only.", "resolution_criteria_he": "מתקיים אם בתוך חלון ה-24 שעות: צה\\"ל או כוחות ארה\\"ב תוקפים יעד בשטח איראן, או שאיראן משגרת טילים או כלי טיס בלתי מאוישים ישירות משטחה לעבר ישראל או לעבר יעד אמריקאי. יירוט של כלי טיס איראני בדרך ופעולות של שלוחים (חיזבאללה, החות''ים ואחרים) אינם נחשבים כהתרחשות – הם משמשים כאותות בלבד."}]'::jsonb)
on conflict do nothing;

